const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','smart-sync.js','deck-midi.js','midi.js','panels.js','fx-tempo-capture-worklet.js','relative-tempo-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
const click=s=>{assert($(s),'Missing '+s);$(s).click();},value=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);},button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`;
async function until(fn,label){const deadline=performance.now()+15000;while(!fn()){assert(performance.now()<deadline,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
function metrics(data,sr){let energy=0,peak=0,finite=true;const crossings=[];for(let i=0;i<data.length;i++){const x=data[i];finite&&=Number.isFinite(x);energy+=x*x;peak=Math.max(peak,Math.abs(x));if(i&&data[i-1]<0&&x>=0)crossings.push(i-1-data[i-1]/(x-data[i-1]));}return{frames:data.length,finite,rms:Math.sqrt(energy/data.length),peak,hz:crossings.length>1?(crossings.length-1)*sr/(crossings.at(-1)-crossings[0]):null};}
let app;
async function run(){const {state,engine}=app;$('#relative-run').disabled=true;const r={startedAt:new Date().toISOString(),completed:false,scope:'Actual production app GUI-handler and MIDI-editor inputs, generated engine buffers, post-master stereo Float32 and whole recording. Not physical MIDI, native, file import, music, exact vendor taper or full relative-mode acceptance.',criteria:{settleSeconds:.3,captureSeconds:.3,frequencyToleranceHz:.3,minimumRMS:.005,silencePeak:.000001},cases:[],errors:[]};let witnesses=[];
 function output(){const safe={...r,cases:r.cases.map(c=>({...c,pcm:c.pcm?.map(p=>({...p,base64:'Retained in private original'}))})),recording:r.recording?{...r.recording,base64:'Retained in private original'}:undefined};$('#relative-results').textContent=JSON.stringify(safe,null,2);$('#relative-original').textContent=JSON.stringify(r,null,2);}
 const midiOpen=()=>click('[data-panel="midi"]');
 function packet(type,channel,number,v){value('#midi-type',type);value('#midi-channel',channel);value('#midi-number',number);value('#midi-test-value',v);click('#midi-send');}
 function fader(raw,ignore=false){midiOpen();packet('CC',ignore?6:3,8,raw>>7);packet('CC',ignore?6:3,40,raw&127);click('#modal-close');}
 async function sample(name,rates,action=()=>{},{silence=false}={}){const c={name,expectedRates:rates,expectedFrequencies:rates.map((v,i)=>silence?0:(i?550:330)*v)};r.cases.push(c);$('#relative-status').textContent='Running '+name;await action();await until(()=>state.decks.slice(0,2).every((d,i)=>Math.abs(d.rate-rates[i])<1e-8&&!d.processing),'Expected rates');await sleep(300);
  c.rates=state.decks.slice(0,2).map(d=>d.rate);c.sync=state.decks.slice(0,2).map(d=>({sync:d.sync,state:d.syncState,position:engine.position(d),playing:d.playing}));
  const id=r.cases.length,raw=await Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM capture timeout')),5000);w.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate*.3)});})));c.pcm=[];c.measured=[];
  for(let i=0;i<2;i++){const bytes=new Uint8Array(raw[i].data.buffer);c.pcm.push({startFrame:raw[i].startFrame,frames:raw[i].data.length,sha256:await hash(bytes),base64:base64(bytes)});c.measured.push(metrics(raw[i].data,engine.ctx.sampleRate));}
  c.passed=c.measured.every((m,i)=>m.finite&&(c.expectedFrequencies[i]===0?m.peak<r.criteria.silencePeak:m.rms>=r.criteria.minimumRMS&&Math.abs(m.hz-c.expectedFrequencies[i])<=r.criteria.frequencyToleranceHz));assert(c.passed,'Actual output mismatch for '+name);output();}
 try{r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical graph must be muted');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],[120,100],state.fxTempo);
  await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);for(let i=0;i<2;i++){const w=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,i);w.connect(engine.ctx.destination);witnesses.push(w);}r.sampleRate=engine.ctx.sampleRate;
  for(let i=0;i<2;i++){const d=state.decks[i],b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*24,engine.ctx.sampleRate);for(let n=0;n<b.length;n++)b.getChannelData(i)[n]=.05*Math.sin(2*Math.PI*(i?550:330)*n/b.sampleRate);Object.assign(d.track,{bpm:i?100:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration:24,analyzed:true});Object.assign(d,{rate:1,position:0,pitchRange:8,keylock:false,keyShift:0,reverse:false,loop:false,sync:false,syncState:'off'});engine.clearDeckScratchCache(i);engine.buffers.set(d.track.id,b);engine.mix(i,'level',.8);}
  click('[data-panel="settings"]');value('[data-setting="Sync Mode"]','Smart Sync');$('[data-setting="Sync Mode"]').dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');midiOpen();click('#midi-reset');
  for(const [target,type,channel,number,encoding]of [['Deck 2 tempo','CC',3,8,'14-bit absolute'],['Deck 2 tempo ignore','CC',6,8,'14-bit absolute']]){value('#midi-target',target);value('#midi-type',type);value('#midi-channel',channel);value('#midi-number',number);value('#midi-encoding',encoding);click('#midi-add');}click('#modal-close');
  click(button(0,'sync'));click(button(0,'play'));await until(()=>state.decks[0].playing,'Primary playback');click(button(1,'sync'));click(button(1,'play'));await until(()=>state.decks[1].playing&&state.decks[1].syncState==='beat'&&!state.decks[1].processing,'Secondary playback');await engine.recordStart();
  const step=1024/8191*.08,shared=(1.2+step)*100/120;
  await sample('Unknown physical position after second OFF takes over on its first packet',[1,1],()=>{click(button(1,'syncOff'));click(button(1,'syncOff'));fader(8192);});click(button(1,'sync'));await until(()=>state.decks[1].syncState==='beat'&&Math.abs(state.decks[1].rate-1.2)<1e-8,'Re-engage secondary');
  await sample('Synced20percent center establishes no-jump physical baseline',[1,1.2],()=>fader(8192));
  await sample('Hardware fader movement changes both synced decks',[shared,1.2+step],()=>fader(9216));
  await sample('First OFF keeps relative tempo',[shared,1.2+step],()=>click(button(1,'syncOff')));assert(state.decks[1].syncState==='relative','First OFF must retain relative mode');
  await sample('Relative fader moves its deck without changing the primary',[shared,1.2+2*step],()=>fader(10240));
  await sample('Shift-ignore repositions physical fader',[shared,1.2+2*step],()=>fader(4096,true));
  await sample('Returning from Shift-ignore has no tempo jump',[shared,1.2+2*step],()=>fader(4096));
  await sample('Relative movement resumes after reposition',[shared,1.2+2*step+.01],()=>fader(5120));
  await sample('Second OFF immediately restores cached absolute pitch',[shared,1-.03],()=>click(button(1,'syncOff')));assert(state.decks[1].syncState==='off','Second OFF must leave relative mode');
  await sample('Reload from REL restores the hardware pitch before playback',[shared,1-.02],async()=>{click(button(1,'play'));await until(()=>!state.decks[1].playing,'Pause for reload');click(button(1,'sync'));await until(()=>state.decks[1].sync&&Math.abs(state.decks[1].rate-(1.2+step))<1e-8,'Arm before relative reload');click(button(1,'syncOff'));fader(6144);await until(()=>Math.abs(state.decks[1].rate-(1.2+step+.01))<1e-8,'Relative move before reload');r.reloadBefore={rate:state.decks[1].rate,state:state.decks[1].syncState};const id=state.decks[1].track.id;click(`#tracks [data-track="${id}"]`);click(button(1,'load'));await until(()=>state.decks[1].syncState==='off'&&Math.abs(state.decks[1].rate-.98)<1e-8,'Known physical pitch on reload');r.reloadAfter={rate:state.decks[1].rate,state:state.decks[1].syncState};click(button(1,'play'));await until(()=>state.decks[1].playing,'Reloaded playback');});
  await sample('Both Stop controls silence the captured master',[shared,1-.02],async()=>{click(button(0,'play'));click(button(1,'play'));await until(()=>!state.decks[0].playing&&!state.decks[1].playing,'Stop');},{silence:true});
 }catch(error){r.errors.push({message:error.message,stack:error.stack});}
 finally{for(const d of state.decks)engine.pause(d);if(engine.recording){const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer()),b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));let finite=true;for(let c=0;c<b.numberOfChannels;c++)for(const x of b.getChannelData(c))finite&&=Number.isFinite(x);r.recording={bytes:bytes.length,sha256:await hash(bytes),base64:base64(bytes),format:blob.type,sampleRate:b.sampleRate,frames:b.length,channels:b.numberOfChannels,allFinite:finite};}for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.completed=r.cases.length===11&&r.cases.every(c=>c.passed)&&!r.errors.length&&r.sourceStable&&r.recording?.allFinite;r.finishedAt=new Date().toISOString();output();$('#relative-status').textContent=r.completed?'Scoped controller relative-tempo workflow passed; stopped':'Failed: '+r.errors.map(e=>e.message).join('; ');}
}
$('#relative-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#relative-run').disabled=false;$('#relative-status').textContent='Ready';}boot().catch(error=>$('#relative-status').textContent=error.message);
